  line_arithmetic: 'line total wrong',
};
const FORM_PATH = '/form/6f0a3c1e-7a52-4b6e-9d0f-2f4c1d5a8b01';
// <<< page-helpers
// One approval, laid out for a decision: the verdict and why, the invoice, the GST check, and every line
// next to the purchase order line it was matched to.
const req = $('Read Request').first().json;
const detail = $input.first().json.detail;
const back = ' <a href="' + FORM_PATH + '">Back to the pending approvals</a>.';
if (!detail) {
  return [{ json: { state: 'missing', title: 'Not found', message: 'There is no approval number ' + esc(req.approval_id) + '.' + back } }];
}
const a = detail.approval;
const inv = detail.invoice;
if (a.status !== 'pending') {
  const reason = a.comment ? ' Reason given: ' + esc(a.comment) : '';
  return [
    {
      json: {
        state: 'decided',
        title: 'Already ' + esc(a.status),
        message: 'Invoice ' + esc(inv.invoice_number) + ' was ' + esc(a.status) + ' by ' + esc(a.decided_by) + ' on ' + esc(when(a.decided_at)) + '.' + reason + back,
      },
    },
  ];
}

const codes = [...(a.reason_codes ?? []), ...(a.review_reasons ?? [])];
const why = codes.length
  ? '<ul>' + codes.map((c) => '<li><b>' + esc(c) + '</b>: ' + esc(reasonText(c)) + '</li>').join('') + '</ul>'
  : '<p>Every check passed.</p>';

const gst = detail.gst;
const gstLine = gst
  ? '<p>GST: stated ' + esc(dollars(gst.stated_cents)) + ', expected ' + esc(dollars(gst.expected_cents)) +
    ' (tolerance ' + esc(dollars(gst.tolerance_cents)) + ', judged against the ' + (gst.basis === 'po' ? 'purchase order' : 'invoice itself') + ').</p>'
  : '';

const lines = (detail.lines ?? [])
  .map((l) => {
    const matched = l.po_line_no
      ? 'PO line ' + esc(l.po_line_no) + ': ' + esc(l.po_description) + ' (ordered ' + esc(qty(l.po_quantity)) + ' at ' + esc(dollars(l.po_unit_price_cents)) +
        ', received ' + esc(qty(l.received_quantity)) + ', billed before ' + esc(qty(l.billed_before)) + '; matched by ' + esc(l.match_method) + ')'
      : 'not matched to a PO line';
    const issues = (l.issues ?? []).map((i) => esc(ISSUE_TEXT[i] ?? i)).join(', ');
    return (
      '<tr><td>' + esc(l.line_no) + '</td><td>' + esc(l.description) + '</td><td>' + esc(qty(l.quantity)) + '</td>' +
      '<td>' + esc(dollars(l.unit_price_cents)) + '</td><td>' + esc(dollars(l.line_total_cents)) + '</td>' +
      '<td>' + matched + '</td><td>' + (issues || '&mdash;') + '</td></tr>'
    );
  })
  .join('');

const needsComment = a.recommended_status !== 'recommend_approve';
const html =
  '<h3>' + esc(VERDICT[a.recommended_status] ?? a.recommended_status) + ': invoice ' + esc(inv.invoice_number) + '</h3>' +
  '<p>You are deciding as <b>' + esc(req.user.email) + '</b>. Your account is recorded as the approver.</p>' +
  why +
  '<table>' +
  '<tr><th>Supplier</th><td>' + esc(inv.supplier_name) + ' (ABN ' + esc(inv.supplier_abn) + ')</td></tr>' +
  '<tr><th>Invoice date</th><td>' + esc(inv.invoice_date) + (inv.due_date ? ', due ' + esc(inv.due_date) : '') + '</td></tr>' +
  '<tr><th>Purchase order</th><td>' + esc(inv.po_number ?? 'none on the invoice') + (detail.purchase_order ? ' (found)' : '') + '</td></tr>' +
  (inv.duplicate_of_invoice_number ? '<tr><th>Duplicate of</th><td>' + esc(inv.duplicate_of_invoice_number) + '</td></tr>' : '') +
  '<tr><th>Subtotal / GST / Total</th><td>' + esc(dollars(inv.subtotal_cents)) + ' / ' + esc(dollars(inv.gst_cents)) + ' / ' + esc(dollars(inv.total_cents)) + '</td></tr>' +
  '</table>' +
  gstLine +
  '<table><tr><th>#</th><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th><th>Purchase order line</th><th>Issues</th></tr>' + lines + '</table>' +
  '<p>' + (needsComment
    ? 'Give a reason whichever way you decide: this invoice was not a clean recommendation.'
    : 'A reason is optional for approving, and required for rejecting.') + '</p>';
return [{ json: { state: 'open', needs_comment: needsComment, html } }];

// The decision page's answer, plus who is deciding. No answer means the session timed out: nothing is recorded.
const answer = $input.first().json;
const req = $('Read Request').first().json;
const choice = String(answer.Decision ?? '').trim().toLowerCase();
const decision = choice === 'approve' ? 'approved' : choice === 'reject' ? 'rejected' : null;
if (decision === null) return [{ json: { abandoned: true } }];
return [
  {
    json: {
      abandoned: false,
      approval_id: req.approval_id,
      decision,
      approver: req.user.email,
      comment: typeof answer.Comment === 'string' ? answer.Comment : '',
      context: { user_id: String(req.user.id ?? ''), execution_id: $execution.id, workflow_id: $workflow.id, workflow_name: $workflow.name },
    },
  },
];

