};
const FORM_PATH = '/form/6f0a3c1e-7a52-4b6e-9d0f-2f4c1d5a8b01';
// <<< page-helpers
// Tell the person what happened. Only a `recorded` result changed anything.
const r = $input.first().json.result;
const p = $('Prepare Decision').first().json;
const back = ' <a href="' + FORM_PATH + '">Back to the pending approvals</a>.';
let title;
let message;
switch (r.result) {
  case 'recorded':
    title = 'Recorded: ' + esc(r.decision);
    message = 'Approval ' + esc(r.approval_id) + ' was ' + esc(r.decision) + ' by ' + esc(r.decided_by) + '.' + back;
    break;
  case 'comment_required':
    title = 'Not recorded: a reason is required';
    message = 'Nothing was recorded. A reason is required to approve a flagged or doubtful invoice, and to reject any invoice. Open the approval again from the list and give one.' + back;
    break;
  case 'already_decided':
    title = 'Not recorded: already ' + esc(r.decision);
    message = 'Someone else got there first: it was ' + esc(r.decision) + ' by ' + esc(r.decided_by) + ' on ' + esc(when(r.decided_at)) + '. Your decision was not applied.' + back;
    break;
  case 'not_found':
    title = 'Not recorded: not found';
    message = 'There is no approval number ' + esc(p.approval_id) + '.' + back;
    break;
  default:
    title = 'Not recorded';
    message = esc(r.reason ?? 'The decision was not accepted.') + back;
}
return [{ json: { title, message } }];

